import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Navigate, NavLink, Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { Home, PlusSquare, User, LogOut, Compass, Image, X, Upload } from 'lucide-react';
import Login from './pages/Login';
import Feed from './pages/Feed';
import Profile from './pages/Profile';

axios.defaults.baseURL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

function AppContent() {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('nipix_token'));
  const [loading, setLoading] = useState(true);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [caption, setCaption] = useState('');
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [uploading, setUploading] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    const fetchCurrentUser = async () => {
      if (token) {
        axios.defaults.headers.common['x-auth-token'] = token;
        try {
          const res = await axios.get('/auth/me');
          setUser(res.data);
        } catch (err) {
          console.error('Session expired or invalid token:', err);
          handleLogout();
        }
      }
      setLoading(false);
    };
    fetchCurrentUser();
  }, [token]);

  const handleLogin = (data) => {
    localStorage.setItem('nipix_token', data.token);
    axios.defaults.headers.common['x-auth-token'] = data.token;
    setToken(data.token);
    setUser(data.user);
    navigate('/feed');
  };

  const handleLogout = () => {
    localStorage.removeItem('nipix_token');
    delete axios.defaults.headers.common['x-auth-token'];
    setToken(null);
    setUser(null);
    navigate('/login');
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    if (!imageFile) return alert('Please select an image to post');

    setUploading(true);
    const formData = new FormData();
    formData.append('image', imageFile);
    formData.append('caption', caption);

    try {
      await axios.post('/posts', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setCaption('');
      setImageFile(null);
      setImagePreview(null);
      setIsCreateOpen(false);
      // Trigger feed refresh by dispatching a custom event or navigating
      window.dispatchEvent(new Event('postCreated'));
      navigate('/feed');
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to upload post');
    } finally {
      setUploading(false);
    }
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', height: '100vh', justifyContent: 'center', alignItems: 'center', background: '#0f0f12', color: '#fff' }}>
        <div style={{ textAlign: 'center' }}>
          <h1 className="brand-logo" style={{ fontSize: '3.5rem', marginBottom: '16px' }}>Nipix</h1>
          <p style={{ color: '#9ca3af', fontSize: '0.9rem' }}>Loading visual world...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="app-container">
      {user && (
        <aside className="sidebar">
          <div>
            <div className="brand-container" style={{ padding: '8px 12px 28px 12px' }}>
              <Link to="/feed" className="brand-logo">Nipix</Link>
            </div>

            <nav style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <NavLink to="/feed" className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}>
                <Home size={22} />
                <span>Home Feed</span>
              </NavLink>

              <button onClick={() => setIsCreateOpen(true)} className="nav-item">
                <PlusSquare size={22} />
                <span>Create Post</span>
              </button>

              <NavLink to={`/profile/${user.username}`} className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}>
                {user.profilePic ? (
                  <img src={user.profilePic} alt="avatar" style={{ width: '22px', height: '22px', borderRadius: '50%', objectFit: 'cover' }} />
                ) : (
                  <User size={22} />
                )}
                <span>Profile ({user.username})</span>
              </NavLink>
            </nav>
          </div>

          <div style={{ paddingTop: '16px', borderTop: '1px solid var(--border-color)' }}>
            <button onClick={handleLogout} className="nav-item" style={{ color: '#ef4444' }}>
              <LogOut size={22} />
              <span>Logout</span>
            </button>
          </div>
        </aside>
      )}

      <main className="main-content">
        <Routes>
          <Route path="/login" element={!user ? <Login onLogin={handleLogin} /> : <Navigate to="/feed" />} />
          <Route path="/feed" element={user ? <Feed currentUser={user} /> : <Navigate to="/login" />} />
          <Route path="/profile/:username" element={user ? <Profile currentUser={user} onUpdateUser={setUser} /> : <Navigate to="/login" />} />
          <Route path="/" element={user ? <Navigate to="/feed" /> : <Navigate to="/login" />} />
        </Routes>
      </main>

      {/* Create Post Modal */}
      {isCreateOpen && (
        <div className="modal-overlay" onClick={() => setIsCreateOpen(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', paddingBottom: '12px', borderBottom: '1px solid var(--border-color)' }}>
              <h3 style={{ fontSize: '1.2rem', fontWeight: '700', color: '#fff' }}>Create New Post</h3>
              <button onClick={() => setIsCreateOpen(false)} style={{ background: 'none', border: 'none', color: '#9ca3af', cursor: 'pointer' }}>
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleCreatePost}>
              {!imagePreview ? (
                <label style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '220px', border: '2px dashed var(--border-color)', borderRadius: '12px', cursor: 'pointer', background: 'var(--bg-input)', marginBottom: '16px' }}>
                  <Upload size={40} color="#0095f6" style={{ marginBottom: '12px' }} />
                  <span style={{ fontWeight: '600', color: '#fff', fontSize: '0.95rem' }}>Select Photo to Upload</span>
                  <span style={{ color: '#9ca3af', fontSize: '0.8rem', marginTop: '4px' }}>PNG, JPG or JPEG</span>
                  <input type="file" accept="image/*" onChange={handleImageChange} style={{ display: 'none' }} required />
                </label>
              ) : (
                <div style={{ position: 'relative', marginBottom: '16px', borderRadius: '12px', overflow: 'hidden', maxHeight: '300px', textAlign: 'center', background: '#000' }}>
                  <img src={imagePreview} alt="Preview" style={{ maxHeight: '300px', maxWidth: '100%', objectFit: 'contain' }} />
                  <button type="button" onClick={() => { setImageFile(null); setImagePreview(null); }} style={{ position: 'absolute', top: '10px', right: '10px', background: 'rgba(0,0,0,0.7)', border: 'none', color: '#fff', borderRadius: '50%', padding: '6px', cursor: 'pointer' }}>
                    <X size={18} />
                  </button>
                </div>
              )}

              <div style={{ marginBottom: '20px' }}>
                <textarea
                  placeholder="Write a captivating caption..."
                  value={caption}
                  onChange={(e) => setCaption(e.target.value)}
                  rows={3}
                  className="input-field"
                  style={{ resize: 'none' }}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
                <button type="button" onClick={() => setIsCreateOpen(false)} className="btn-secondary">
                  Cancel
                </button>
                <button type="submit" disabled={uploading || !imageFile} className="btn-primary" style={{ opacity: uploading || !imageFile ? 0.6 : 1 }}>
                  {uploading ? 'Sharing...' : 'Share Post'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default function App() {
  return (
    <Router>
      <AppContent />
    </Router>
  );
}
